"use client"
//import Getuserandpost ,{Crpost} from "@/app/actions/post";
import Bccrtpost, { Bcgetpost } from "@/app/actions/bcpost";
import { useState } from "react";

interface Postblock{
    title:string,
    _id?:string,
    content:string
}

export default   function Posthandler(){
    //const[postusername,setPostusername]=useState("")
    const[title,setTitle]=useState("")
    const[content,setContent]=useState("")
    const[postlist,setPostlsit]=useState<Postblock[]>([])
const [searchpostusername,setSeaerchpostusername]=useState("")
//const[name,setName]=useState("")
const[loading,setLoading]=useState(false)
const[createpostname,setCreatepostname]=useState("")

    const crtpost=async(e:React.FormEvent)=>{
        e.preventDefault()
        const res=await Bccrtpost({
            title,content,name:createpostname
        })
        if(res.success){
           alert("post created")
        }else{
 alert("failed to create post")
        }
    }

    const getpost= async()=>{
        if(!searchpostusername){
            
       alert("user name missing or not found")
                    }
setLoading(true)
try{
    const res=await Bcgetpost(searchpostusername)
    if(!searchpostusername){
        alert (" pleasue enter a username")
    }
    if(res.success){
        setPostlsit(res.data || [])

    }else{
        alert("failed to post")
    }
}catch(error){
    console.error(error)
} finally{
    setLoading(false)
}

    }

    return(
        <div className="flex flex-col gap-5">
          <form onSubmit={crtpost}>

            <input type="text" 
            value={title}
            onChange={(e)=>setTitle(e.target.value)}
            placeholder="enetr your title"
            />

            <input type="text"
            value={content}
            onChange={(e)=>setContent(e.target.value)}
            placeholder="enter your content here"
            />

            <input type="text"
            value={createpostname}
            onChange={(e)=>setCreatepostname(e.target.value)}
            />

            <button className="btn bg-orange-400 text-white" type="submit">Post</button>
          </form>
          
<input value={searchpostusername}
placeholder="enter username"
onChange={(e)=>setSeaerchpostusername(e.target.value)}
/>
<button type="button" className="btn btn-secondary btn-soft" onClick={getpost}>Getpost</button>
          <div className="flex felx-col gap-2 px-2 py-4">
            {postlist.map((ele)=>(
                <div key={ele._id} className="flex flex-col gap-1">
                    {ele.title} {ele.content}
                    </div>
            ))}
          </div>
        </div>
    )

}