"use client"
//import handlesubmit,{Getuser} from "@/app/actions/server"
import Bchandlesubmit, { Bcgetuser } from "@/app/actions/bcuser"
import { useState } from "react"

interface UsrLst{
    name:string,
    _id?:string
}

export default function Userreg(){
    const[name,setName]=useState("")
    const[userId,setUserId]=useState("")
    const[userlist,setUserlist]=useState<UsrLst[]>([])

    const sub=async (e:React.FormEvent)=>{
        e.preventDefault()
        const res=await Bchandlesubmit({
            name,userId
        })
        if(res.success){
            alert("user created")
        }
        else{
            alert("failed to create user")
        }
    }

    const gt=async()=>{
        const ft=await Bcgetuser()
        if(ft.success){
            setUserlist(ft.data)
        }else{
            alert("user list not found")
        }
    }

return(
<div className="flex flex-col jsutify-center items-center">

    <form onSubmit={sub} className="felx flex-col px-2 py-4 gap-5">

        <input type="text" placeholder="enter your name"
        value={name} 
        onChange={(e)=>setName(e.target.value)}
        />

         <input type="text" placeholder="enter your userId"
        value={userId} 
         onChange={(e)=>setUserId(e.target.value)}
        />

<button className="btn btn-secondary" type="submit">
    Submit
</button>
    </form>

<button type="button" className="btn btn-ghost" onClick={gt}>Get alluser</button>



<div className="flex felx-col">
    {userlist.map((ele)=>(
        <div key={ele._id} className="flex gap-2">
{ele.name}
            </div>
    ))}
</div>
</div>
)
}

